//! Dusty's own icon set (app/assets/icons/ui, generated by scripts/ui-icons/gen.py), embedded in the binary.
//!
//! The icons are multi-colored, so they go through `img()` (resvg, full color), not `svg()` (a one-color mask).
//! GPUI rasterizes an SVG image once, at 2× its own `width`/`height`. Drawn at any other size it gets resampled
//! and goes soft, so every icon is asked for at the size it's drawn: `icons/ui/<px>/<name>.svg` serves the file
//! with its width and height rewritten to `<px>`, which rasterizes at exactly the Retina pixel grid.

use std::borrow::Cow;

use gpui::*;

macro_rules! icon_set {
    ($($variant:ident => $file:literal),* $(,)?) => {
        /// One of Dusty's UI icons.
        #[derive(Clone, Copy, PartialEq, Eq, Debug)]
        pub enum Ico { $($variant),* }

        impl Ico {
            #[allow(dead_code)]
            pub const ALL: &'static [Ico] = &[$(Ico::$variant),*];

            pub fn name(self) -> &'static str {
                match self { $(Ico::$variant => $file),* }
            }

            fn bytes(self) -> &'static [u8] {
                match self { $(Ico::$variant => include_bytes!(concat!("../../assets/icons/ui/", $file, ".svg"))),* }
            }

            fn from_name(name: &str) -> Option<Ico> {
                match name { $($file => Some(Ico::$variant),)* _ => None }
            }
        }
    };
}

icon_set! {
    Build => "build", CacheDev => "cache-dev", CacheApp => "cache-app", Junk => "junk", Docker => "docker",
    Redownload => "redownload", Reveal => "reveal", Never => "never", Trash => "trash", PutBack => "put-back",
    Search => "search", Settings => "settings", Back => "back", Check => "check", Warning => "warning",
    Lock => "lock", Practice => "practice", Sparkle => "sparkle", Paw => "paw", Gift => "gift", Party => "party",
    Broom => "broom", Schedule => "schedule", Uninstall => "uninstall", BigFiles => "big-files", Usage => "usage",
    History => "history", Telescope => "telescope", Wrench => "wrench", Oops => "oops", Relief => "relief",
    Dizzy => "dizzy", Menu => "menu",
    // the agents in Look further (their ACP registry icons, in their colors)
    LogoClaude => "logo-claude", LogoCodex => "logo-codex", LogoGemini => "logo-gemini", LogoCopilot => "logo-copilot",
    LogoCursor => "logo-cursor", LogoOpencode => "logo-opencode",
}

/// The icons' native size (their viewBox and width/height).
const NATIVE: u32 = 48;

/// Serves `icons/ui/<name>.svg` as is and `icons/ui/<px>/<name>.svg` resized to `<px>`.
pub struct Assets;

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        Ok(resolve(path))
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        Ok(Ico::ALL.iter().map(|i| SharedString::from(format!("icons/ui/{}.svg", i.name()))).filter(|p| p.starts_with(path)).collect())
    }
}

fn resolve(path: &str) -> Option<Cow<'static, [u8]>> {
    let rest = path.strip_prefix("icons/ui/")?.strip_suffix(".svg")?;
    let (px, name) = match rest.split_once('/') {
        Some((px, name)) => (px.parse::<u32>().ok()?, name),
        None => (NATIVE, rest),
    };
    let ico = Ico::from_name(name)?;
    if px == NATIVE {
        return Some(Cow::Borrowed(ico.bytes()));
    }
    let svg = std::str::from_utf8(ico.bytes()).ok()?;
    let from = format!(r#"width="{NATIVE}" height="{NATIVE}""#);
    debug_assert!(svg.contains(&from), "{name}.svg has no {from}");
    Some(Cow::Owned(svg.replacen(&from, &format!(r#"width="{px}" height="{px}""#), 1).into_bytes()))
}

/// An icon drawn at `size` points, rasterized for exactly that size.
pub fn icon(i: Ico, size: f32) -> Img {
    icon_raster(i, size, size)
}

/// An icon rasterized for `raster` points but laid out at `size`: for icons that grow or shrink in an animation,
/// so every frame reuses one raster instead of rendering a new one.
pub fn icon_raster(i: Ico, raster: f32, size: f32) -> Img {
    let r = raster.round().max(1.) as u32;
    img(SharedString::from(format!("icons/ui/{r}/{}.svg", i.name()))).size(px(size)).flex_none()
}

#[cfg(test)]
mod tests {
    use super::{resolve, Ico};

    #[test]
    fn every_icon_resolves_at_any_size() {
        for i in Ico::ALL {
            let native = resolve(&format!("icons/ui/{}.svg", i.name())).expect("native");
            assert!(std::str::from_utf8(&native).unwrap().contains(r#"width="48" height="48""#), "{}", i.name());
            let sized = resolve(&format!("icons/ui/20/{}.svg", i.name())).expect("sized");
            let s = std::str::from_utf8(&sized).unwrap();
            assert!(s.contains(r#"width="20" height="20""#) && s.contains(r#"viewBox="0 0 48 48""#), "{}", i.name());
        }
        assert!(resolve("icons/ui/20/nope.svg").is_none());
        assert!(resolve("icons/ui/x/back.svg").is_none());
    }

    #[test]
    fn icon_paths_are_not_mistaken_for_urls() {
        // gpui treats anything that parses as a URI as a download, not an embedded asset
        assert!(gpui::http_client::Uri::try_from("icons/ui/20/back.svg").is_err());
    }
}
